def get_max_triples(n):
    from itertools import combinations

    def value(i):
        return i * i - i + 1

    a = [value(i) for i in range(1, n + 1)]

    count = 0
    for triple in combinations(range(n), 3):
        i, j, k = triple
        if (a[i] + a[j] + a[k]) % 3 == 0:
            count += 1

    return count
